282	+const PUBLIC = createMatchConfig({ kind: "public" });
283	+const PRIVATE = createMatchConfig({ kind: "private" });
284	+const READY = 400;
285	+const DEPARTURE = 900;
286	+const DURATION = 42_000;
287	+
288	+/** Recursively frozen, so a step that mutated its input would throw. */
289	+function deepFreeze<T>(value: T): T {
290	+  if (typeof value === "object" && value !== null && !Object.isFrozen(value)) {
291	+    Object.freeze(value);
292	+    for (const child of Object.values(value)) deepFreeze(child);
293	+  }
294	+  return value;
295	+}
296	+
297	+/** Drives one match through frozen states and inputs, keeping every event. */
298	+class Script {
299	+  state: MatchState;
300	+  events: MatchEvent[] = [];
301	+  last: readonly MatchEvent[] = [];
302	+
303	+  constructor(
304	+    readonly config: MatchConfig,
305	+    tick = 0,
306	+  ) {
307	+    this.state = deepFreeze(createMatchState(config, tick));
308	+  }
309	+
310	+  at(tick: number, ...reports: MatchReport[]): this {
311	+    const input: MatchInput = deepFreeze({ tick, reports });
312	+    const stepped = stepMatch(this.config, this.state, input);
313	+    this.state = deepFreeze(stepped.state);
314	+    this.last = stepped.events;
315	+    this.events.push(...stepped.events);
316	+    return this;
317	+  }
318	+
319	+  kinds(): string[] {
320	+    return this.last.map((event) => event.kind);
321	+  }
322	+}
323	+
324	+const join = (...ids: string[]): MatchReport[] => ids.map((playerId) => ({ kind: "join", playerId }));
325	+const leave = (...ids: string[]): MatchReport[] => ids.map((playerId) => ({ kind: "leave", playerId }));
326	+const start = (playerId: string): MatchReport => ({ kind: "start", playerId });
327	+const claimEnd = (tick: number, winner: string): MatchReport => ({ kind: "match-ended", tick, reason: "claim", winner });
328	+const deadlineEnd = (tick: number): MatchReport => ({ kind: "match-ended", tick, reason: "deadline", winner: null });
329	+const FAULT: MatchReport = { kind: "fault" };
330	+const EIGHT = ["p1", "p2", "p3", "p4", "p5", "p6", "p7", "p8"];
331	+
332	+/** A private match of `ids` that the first id starts at tick 10: control starts at 410. */
333	+function privateRunning(ids: string[]): Script {
334	+  return new Script(PRIVATE).at(1, ...join(...ids)).at(10, start(ids[0]!)).at(10 + READY);
335	+}
336	+
337	+describe("match config", () => {
338	+  it("takes the public seats and the private limits from the content rules and the duration from the claim rules", () => {
339	+    expect(PUBLIC).toEqual({ kind: "public", custom: false, seats: 8, minPlayers: 8, readyTicks: 400, departureTicks: 900, durationTicks: 42_000, startingGold: 50 });
340	+    expect(PRIVATE).toEqual({ kind: "private", custom: true, seats: 8, minPlayers: 2, readyTicks: 400, departureTicks: 900, durationTicks: 42_000, startingGold: 50 });
341	+    expect(() => createMatchConfig({ kind: "private", rules: { ...matchRules, readyTicks: 0 } })).toThrow(/readyTicks/);
342	+    expect(() => createMatchConfig({ kind: "private", durationTicks: 0 })).toThrow(RangeError);
343	+    expect(() => createMatchConfig({ kind: "ranked" as never })).toThrow(RangeError);
344	+    expect(createMatchState(PRIVATE)).toMatchObject({ tick: 0, phase: "lobby", custom: true, players: [], host: null, end: null, results: null });
345	+  });
346	+});
347	+
348	+describe("phases (§2)", () => {
349	+  it("moves a full public lobby through ready, departure and exploration on their ticks", () => {
350	+    const script = new Script(PUBLIC).at(1, ...join(...EIGHT.slice(0, 7)));
351	+    expect(script.state.phase).toBe("lobby");
352	+    script.at(5, ...join("p8"));
353	+    expect(script.state.phase).toBe("ready");
354	+    expect(script.state.readyTick).toBe(5);
355	+    expect(script.last.at(-1)).toEqual({ kind: "phase-changed", tick: 5, from: "lobby", to: "ready" });
356	+    script.at(5 + READY - 1);
357	+    expect(script.state.phase).toBe("ready");
358	+    script.at(5 + READY);
359	+    expect(script.last).toEqual([
360	+      { kind: "phase-changed", tick: 405, from: "ready", to: "departure" },
361	+      { kind: "control-started", tick: 405 },
362	+    ]);
363	+    expect(script.state).toMatchObject({ phase: "departure", controlStartTick: 405, readyTick: null });
364	+    script.at(405 + DEPARTURE - 1);
365	+    expect(script.state.phase).toBe("departure");
366	+    script.at(405 + DEPARTURE);
367	+    expect(script.last).toEqual([{ kind: "phase-changed", tick: 1305, from: "departure", to: "exploration" }]);
368	+    script.at(5_000, deadlineEnd(5_000));
369	+    expect(script.state.phase).toBe("ended");
370	+    expect(script.events.filter((event) => event.kind === "phase-changed").map((event) => event.kind === "phase-changed" && event.to)).toEqual([
371	+      "ready",
372	+      "departure",
373	+      "exploration",
374	+      "ended",
375	+    ]);
376	+    expect(script.state.custom).toBe(false);
377	+    expect(script.state.results!.custom).toBe(false);
378	+  });
