380	+  it("refuses a start request in a public match and never starts one short-handed", () => {
381	+    const script = new Script(PUBLIC).at(1, ...join(...EIGHT.slice(0, 7)), start("p1"));
382	+    expect(script.last.at(-1)).toEqual({ kind: "start-refused", tick: 1, playerId: "p1", reason: "public" });
383	+    expect(script.state).toMatchObject({ phase: "lobby", host: null });
